import{c as a,Q as s,j as t,m as r}from"./chunks/framework.g_l1frA7.js";const h=JSON.parse('{"title":"Data Storage","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/data-storage.md","filePath":"configuration/data-storage.md","lastUpdated":null}'),n={name:"configuration/data-storage.md"};function i(o,e,d,c,p,l){return s(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="data-storage" tabindex="-1">Data Storage <a class="header-anchor" href="#data-storage" aria-label="Permalink to &quot;Data Storage&quot;">​</a></h1><p>Where FinSight keeps data, and what to back up.</p><h2 id="on-disk-layout" tabindex="-1">On-disk layout <a class="header-anchor" href="#on-disk-layout" aria-label="Permalink to &quot;On-disk layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data                  # Docker volume finsight-data; native dev ./data</span></span>
<span class="line"><span>├── users.db            # account registry — usernames, Argon2id verifiers, wrapped DB keys, hashed sessions</span></span>
<span class="line"><span>├── session.key         # wraps persisted session keys — back this up</span></span>
<span class="line"><span>└── users/&lt;user-uuid&gt;/</span></span>
<span class="line"><span>    ├── data.sqlcipher   # per-user ledger, budgets, goals, secrets (LLM keys, SimpleFIN URLs)</span></span>
<span class="line"><span>    ├── backups/         # manual + pre-migration snapshots</span></span>
<span class="line"><span>    └── imports/         # authenticated CSV staging</span></span></code></pre></div><ul><li><code>users.db</code> is <strong>plain SQLite</strong>, not SQLCipher — it must be readable before any user key is unwrapped. It contains no financial records, plaintext passwords, or plaintext database keys.</li><li><code>data.sqlcipher</code> is <strong>SQLCipher-encrypted</strong> with a random 32-byte key generated per user.</li><li>Databases are migrated via Refinery files in <code>crates/finsight-core/migrations</code> (currently through <code>V016</code>, next is <code>V017__</code>).</li></ul><h2 id="key-wrapping" tabindex="-1">Key wrapping <a class="header-anchor" href="#key-wrapping" aria-label="Permalink to &quot;Key wrapping&quot;">​</a></h2><p>Per <code>crypto.rs</code>:</p><ul><li>The DB key is stored only wrapped, twice: <ul><li><code>Wrap(KEK1)</code> where <code>KEK1 = Argon2id(password, kek_salt)</code> pinned at m=19456 KiB, t=2, p=1, id v19</li><li><code>Wrap(KEK2)</code> where <code>KEK2 = recovery key bytes</code> (high-entropy, no KDF)</li></ul></li><li>Password verification uses a <strong>separate</strong> Argon2id PHC string (own salt) so the verifier cannot derive the KEK.</li><li>Unwrapped keys exist only in server memory, single-flighted, evicted after 30 minutes idle (unless SSE attached).</li></ul><h2 id="browser-cache" tabindex="-1">Browser cache <a class="header-anchor" href="#browser-cache" aria-label="Permalink to &quot;Browser cache&quot;">​</a></h2><p>A seven-day, <strong>read-only, IndexedDB query cache</strong> (tanstack-query persist) for offline viewing. Encrypted when the PWA has a secure context; purged on logout or authentication failure. The vault is <code>/data</code>, not the cache.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><ul><li><strong>Per-user snapshots</strong> — Settings → Data &amp; backups creates/restores an encrypted snapshot under <code>users/&lt;uuid&gt;/backups/</code> on the server.</li><li><strong>Disaster recovery</strong> — back up the <strong>whole <code>/data</code> volume</strong> so <code>users.db</code> + <code>session.key</code> + every per-user database stay together. A single per-user file without <code>users.db</code> cannot be unwrapped.</li></ul><h2 id="simplefin-provider-secrets" tabindex="-1">SimpleFIN &amp; provider secrets <a class="header-anchor" href="#simplefin-provider-secrets" aria-label="Permalink to &quot;SimpleFIN &amp; provider secrets&quot;">​</a></h2><p>LLM API keys and SimpleFIN access URLs are rows in <code>data.sqlcipher</code>, per user — not a shared keychain. Deleting a user removes that user’s database and all secrets inside it.</p><p>See also: <a href="/FinSight/getting-started/privacy">Privacy &amp; Local Data</a>, <a href="/FinSight/help/security">Security &amp; Privacy</a>.</p>`,15)])])}const g=a(n,[["render",i]]);export{h as __pageData,g as default};
